pm.test("创建成功，状态码为201", function () {
    pm.response.to.have.status(201);
});

const data = pm.response.json();

pm.test("响应包含有效的任务ID", function () {
    pm.expect(data.id).to.be.a("number");
    pm.expect(data.id).to.be.above(0);
});

pm.collectionVariables.set("task_id", data.id);
pm.collectionVariables.set("poll_count", 0);

pm.test("查询成功，状态码为200", function () {
    pm.response.to.have.status(200);
});

const data = pm.response.json();
const taskId = Number(pm.collectionVariables.get("task_id"));
let pollCount = Number(pm.collectionVariables.get("poll_count") || 0);

pm.test("返回正确的任务ID", function () {
    pm.expect(data.id).to.eql(taskId);
});

pm.test("任务状态有效", function () {
    pm.expect(["pending", "running", "success", "failed"])
        .to.include(data.status);
});

if (data.status === "pending" || data.status === "running") {
    pollCount++;

    if (pollCount < 10) {
        pm.collectionVariables.set("poll_count", pollCount);
        pm.execution.setNextRequest("查询测试任务");
    } else {
        pm.test("任务在规定次数内结束", function () {
            pm.expect.fail("轮询10次后任务仍未结束");
        });
        pm.execution.setNextRequest(null);
    }
} else {
    pm.collectionVariables.unset("poll_count");
    pm.execution.setNextRequest("查询任务日志");
}

pm.test("Successful POST request", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

pm.test("日志查询成功", function () {
    pm.response.to.have.status(200);
});

const logs = pm.response.json();
const taskId = Number(
    pm.collectionVariables.get("task_id")
);

pm.test("响应是日志数组", function () {
    pm.expect(logs).to.be.an("array");
    pm.expect(logs.length).to.be.at.least(3);
    pm.expect(logs.length).to.be.at.most(20);
});

pm.test("日志都属于当前任务", function () {
    logs.forEach(function (log) {
        pm.expect(log.task_id).to.eql(taskId);
    });
});

pm.test("任务生命周期正确", function () {
    const statuses = logs.map(log => log.status);

    pm.expect(statuses).to.deep.equal([
        "pending",
        "running",
        "success"
    ]);
});

pm.test("日志按时间升序排列", function () {
    for (let i = 1; i < logs.length; i++) {
        pm.expect(
            new Date(logs[i].created_at).getTime()
        ).to.be.at.least(
            new Date(logs[i - 1].created_at).getTime()
        );
    }
});

pm.test("日志查询成功", function () {
    pm.response.to.have.status(200);
});

const logs = pm.response.json();
const taskId = Number(pm.collectionVariables.get("task_id"));

pm.test("返回结果为非空数组", function () {
    pm.expect(logs).to.be.an("array");
    pm.expect(logs.length).to.be.above(0);
    pm.expect(logs.length).to.be.at.most(20);
});

pm.test("所有日志都属于当前任务", function () {
    logs.forEach(function (log) {
        pm.expect(log.task_id).to.eql(taskId);
    });
});

pm.test("状态和关键词筛选正确", function () {
    logs.forEach(function (log) {
        pm.expect(log.status).to.eql("success");
        pm.expect(log.message.toLowerCase()).to.include("completed");
    });
});

pm.test("报告查询成功", function () {
    pm.response.to.have.status(200);
});

const report = pm.response.json();
const taskId = Number(
    pm.collectionVariables.get("task_id")
);

pm.test("报告属于当前任务", function () {
    pm.expect(report.task.id).to.eql(taskId);
    pm.expect(report.task.status).to.eql("success");
});

pm.test("日志总数正确", function () {
    pm.expect(report.logs).to.be.an("array");
    pm.expect(report.total_logs).to.eql(
        report.logs.length
    );
});

pm.test("执行耗时有效", function () {
    pm.expect(
        report.execution_duration_seconds
    ).to.be.a("number");
    pm.expect(
        report.execution_duration_seconds
    ).to.be.at.least(0);
});

const previousTaskId =
    pm.collectionVariables.get("report_task_id");

const previousGeneratedAt =
    pm.collectionVariables.get("report_generated_at");

if (
    previousTaskId === String(taskId) &&
    previousGeneratedAt
) {
    pm.test("重复查询命中报告缓存", function () {
        pm.expect(report.generated_at).to.eql(
            previousGeneratedAt
        );
    });
}

pm.collectionVariables.set(
    "report_task_id",
    String(taskId)
);

pm.collectionVariables.set(
    "report_generated_at",
    report.generated_at
);

pm.test("成功任务没有失败分析", function () {
    const report = pm.response.json();
    pm.expect(report.failure_analysis).to.eql(null);
});

pm.collectionVariables.set(
    "first_generated_at",
    pm.response.json().generated_at
);

pm.test("查询报告成功", function () {
    pm.response.to.have.status(200);
});

const report = pm.response.json();
const firstGeneratedAt =
    pm.collectionVariables.get("first_generated_at");

pm.test("第二次报告命中Redis缓存", function () {
    pm.expect(report.generated_at).to.eql(firstGeneratedAt);
});

pm.test("非法平台返回422", function () {
    pm.response.to.have.status(422);
});

pm.test("响应包含参数校验错误", function () {
    const data = pm.response.json();
    pm.expect(data).to.have.property("detail");
    pm.expect(data.detail).to.be.an("array");
});

pm.test("不存在的任务返回404", function () {
    pm.response.to.have.status(404);
});

pm.test("响应包含错误信息", function () {
    const data = pm.response.json();
    pm.expect(data).to.have.property("detail");
    pm.expect(data.detail).to.be.a("string");
});
